<script setup lang="ts">import {ref,watch} from 'vue';import * as api from '../api/scenarios';import * as datasets from '../api/datasets';import * as candidates from '../api/candidates';import * as runs from '../api/runs';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const {data,error}=useResource(api.list,[]),{data:ds}=useResource(datasets.list,[]),{data:cs}=useResource(candidates.list,[]);const name=ref('秋季补给预算复核'),dataset=ref('ds-patrol'),radius=ref(4.5),budget=ref(9),maxSites=ref(6),capacityMode=ref(false),selected=ref<string[]>([]),message=ref('');let initialized=false;watch(cs,()=>{if(!initialized&&cs.value.length){selected.value=cs.value.map(x=>x.id);initialized=true}});async function submit(){try{await api.create({name:name.value,dataset_id:dataset.value,candidate_ids:selected.value,radius_km:radius.value,budget:budget.value,max_sites:maxSites.value,capacity_mode:capacityMode.value});refreshResources();message.value=''}catch(e:any){message.value=e.message}}async function execute(id:string){try{const run=await runs.create({scenario_id:id});sessionStorage.setItem('coverage-selected-run',run.id);location.hash='results'}catch(e:any){message.value=e.message}}</script><template><PageTitle chapter="04" title="用同一口径，推演不同预算" description="加权覆盖按新增覆盖权重 / 成本逐点选择；容量推演再叠加日需求与站点日容量约束，限时搜索并给出收益上界。"/><Notice :error="error||message"/><form v-if="user?.role!=='viewer'" class="paper form-grid" @submit.prevent="submit"><label>方案名称<input v-model="name" aria-label="方案名称"/></label><label>需求文件<select v-model="dataset"><option v-for="d in ds" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>覆盖半径（km）<input v-model.number="radius" type="number" min=".1" max="1000" step=".1"/></label><label>总预算（万元）<input v-model.number="budget" type="number" min="0" step=".1"/></label><label>最多选点数<input v-model.number="maxSites" type="number" min="1" max="100"/></label><label class="checkbox"><input v-model="capacityMode" type="checkbox"/>容量推演：按样点日需求与候选日容量整份分配，限时30秒并报告收益上界</label><details><summary>可用候选点 {{selected.length}} / {{cs.length}}</summary><label v-for="c in cs" :key="c.id" class="checkbox"><input v-model="selected" type="checkbox" :value="c.id"/>{{c.name}} · {{c.cost}}万元<template v-if="c.daily_capacity!=null"> · 日容量{{c.daily_capacity}}</template></label></details><button class="primary">保存推演方案</button></form><section class="paper"><h2>预算方案册</h2><article v-for="s in data" :key="s.id" class="record"><div><b>{{s.name}}<span v-if="s.capacity_mode" class="badge mode-badge">容量推演</span></b><small>半径 {{s.radius_km}} km · 预算 {{s.budget}}万元 · 上限 {{s.max_sites}}点 · {{s.candidate_ids.length}}个候选</small></div><button v-if="user?.role!=='viewer'" @click="execute(s.id)">运行覆盖推演 →</button></article></section></template>
<style scoped>.mode-badge{margin-left:10px}</style>
